def run(industry_category, region, player_limit, results_primary, results_secondary, run_today):
    def clean(x):
        return ' '.join(str(x).split()) if x is not None else ''

    industry = clean(industry_category)
    region = clean(region) or 'global'
    try:
        limit = int(player_limit)
    except Exception:
        limit = 5
    limit = max(1, min(5, limit))

    facts = []
    if industry:
        facts.append({'type': 'input', 'label': 'industry_category', 'value': industry})
    facts.append({'type': 'input', 'label': 'region', 'value': region})
    facts.append({'type': 'context', 'label': 'mode', 'value': 'broad public market overview only'})
    facts.append({'type': 'context', 'label': 'scope', 'value': 'publicly available industry players, categories, and market context'})

    seen = set()
    player_count = 0

    def add_results(results, current_count):
        if not isinstance(results, list):
            return current_count
        for r in results:
            if not isinstance(r, dict):
                continue
            title = clean(r.get('title'))
            url = clean(r.get('url'))
            content = clean(r.get('content'))
            blob = ' | '.join([x for x in [title, content] if x])
            low = blob.lower()
            if not blob:
                continue
            if any(word in low for word in ['market leader', 'leading provider', 'vendor', 'brand', 'platform', 'manufacturer', 'chain', 'market share', 'industry players', 'competitors', 'companies', 'players']):
                key = (title.lower() or blob[:80].lower()) + '|' + (url.lower() if url else '')
                if key in seen:
                    continue
                seen.add(key)
                facts.append({'type': 'player', 'name': title[:120] or 'Unnamed source', 'summary': content[:260], 'source': url, 'public': True})
                current_count += 1
                if current_count >= limit:
                    break
        return current_count

    player_count = add_results(results_primary, player_count)
    if player_count < limit:
        player_count = add_results(results_secondary, player_count)

    return {'facts': facts[:limit + 4], 'player_count': player_count, 'industry_category': industry, 'region': region, 'run_today': run_today}

def run(facts):
    facts = facts if isinstance(facts, list) else []
    score = 0
    reasons = []
    escalate = False

    player_hits = 0
    has_targeting = False
    has_broad_context = False

    for f in facts:
        label = (f.get('label') or '').lower()
        value = ' '.join(str(f.get('value') or '').split()).lower()
        if not value:
            continue
        if label == 'mode' and 'broad public market overview' in value:
            has_broad_context = True
            score += 2
        if f.get('type') == 'player':
            player_hits += 1
            score += 1
        if any(term in value for term in ['target', 'track', 'monitor', 'watch list', 'prospect', 'lead list', 'named rival', 'specific competitor', 'account-based']):
            has_targeting = True

    if has_broad_context:
        reasons.append('Output is framed as a broad public market overview.')
    if player_hits:
        reasons.append('public industry player references')
        reasons.append(f'Found {player_hits} public industry player references.')
    if has_targeting:
        reasons.append('Potential targeting language')
        reasons.append('Potential targeting language detected.')
        score -= 3
        escalate = True

    if player_hits == 0:
        reasons.append('No clear public players were identified from the search results.')
        reasons.append('Potential targeting language')
        escalate = True
    if score < 2:
        escalate = True

    verdict = 'safe' if not escalate else 'needs_review'
    return {'score': score, 'verdict': verdict, 'reasons': reasons, 'escalate': escalate}

def run(industry_category, region, facts, judge):
    def clean(x):
        return ' '.join(str(x).split()) if x is not None else ''

    industry = clean(industry_category) or 'the industry'
    region = clean(region) or 'global'
    facts = facts if isinstance(facts, list) else []
    judge = judge if isinstance(judge, dict) else {}

    players = []
    notes = []
    for f in facts:
        if f.get('type') == 'player':
            name = clean(f.get('name'))
            summary = clean(f.get('summary'))
            source = clean(f.get('source'))
            if name:
                line = f'- **{name}**: {summary or "Publicly referenced player."}'
                if source:
                    line += f' ({source})'
                players.append(line)
        elif f.get('type') == 'context':
            notes.append(f'- {clean(f.get("value"))}')

    if judge.get('verdict') == 'safe':
        speech = f'Verdict: safe and broad. I found public industry context for {industry} in {region}, and I will summarize only general players and categories.'
    else:
        speech = f'Verdict: the result needs review. I could not confirm a sufficiently broad, public-only view for {industry} in {region}.'

    if not players:
        players_block = '- No clear public players were identified.'
    else:
        players_block = '\n'.join(players[:5])

    report = f'''# Industry Player Brief

## Verdict
- **Status:** {judge.get('verdict', 'unknown')}
- **Score:** {judge.get('score', 0)}
- **Industry:** {industry}
- **Region:** {region}

## Public players
{players_block}

## Notes
{chr(10).join(notes) if notes else '- Broad public market overview only.'}

## Guardrails
- No individual rival tracking.
- No private or hidden data.
- No ranking of a specific business against named targets.
'''
    return {'speech': speech[:900], 'report': report}
